/* Local-only interface styles. No remote fonts, images, or CDN assets. */

/*
 * Warm-dark tokens reconstructed from the reference screenshot as starting
 * values (UX-01). They are approximate calibration targets, not exact
 * Superhuman values; geometry is calibrated on real displays later.
 */
:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  --surface: #292826;
  --surface-contact: #1f1e1c;
  --surface-raised: #33312e;
  --focus-fill: #474644;
  --focus-accent: #bba5ed;
  --text-primary: #ece9e2;
  /* DESIGN.md Ash: >=4.5:1 on Focus Stone (4.99:1; the old #a8a29a was 3.73:1). */
  --text-secondary: #c0bcb6;
  --unread-marker: #ce9ece;
  --divider: #3b3936;
  --warning: #e4c465;
  --danger: #f1a9a5;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

button {
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 4px;
  padding: 0.15rem 0.5rem;
  font: inherit;
}

button:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

input,
textarea {
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 4px;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: var(--surface);
  color: var(--text-primary);
}

/* UX-13A: disclosed browser workspaces, deliberately not a native tab strip. */
.fixture-workspaces {
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  color: var(--text-primary);
}
.workspace-header {
  padding: 0.4rem 0.75rem;
  border-bottom: 1px solid var(--divider);
  font-size: 0.8rem;
}
.workspace-header p { margin: 0 0 0.35rem; }
.workspace-header nav { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.workspace-header button[aria-current] { background: var(--focus-fill); }
.workspace-panel { flex: 1; min-height: 0; }
.workspace-panel > .app { height: 100%; }

/* Compact Inbox navigation/status header. */
.app-header {
  border-bottom: 1px solid var(--divider);
  padding: 0.35rem 0.75rem;
}

.app-title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.6rem;
}

.rail-brand {
  font-weight: 600;
  color: var(--text-secondary);
  font-size: 0.85rem;
}

.app-title {
  font-size: 0.95rem;
  margin: 0;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.preview-banner {
  background: #3a3116;
  color: #ead48a;
  border: 1px solid #6b5a1e;
  border-radius: 4px;
  padding: 0.25rem 0.5rem;
  margin: 0.25rem 0 0;
  font-size: 0.85rem;
}

.status-line {
  display: flex;
  gap: 1rem;
  font-size: 0.8rem;
  margin: 0.25rem 0 0;
  color: var(--text-secondary);
  flex-wrap: wrap;
}

.status-line [role='alert'] {
  color: var(--danger);
  font-weight: 600;
}

.draft-close-recovery {
  border-bottom: 1px solid var(--divider);
  padding: 0.4rem 0.75rem;
  color: var(--warning);
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
}

.draft-close-recovery p {
  margin: 0;
}

/*
 * Rail + one central list-or-reader surface + contact context. The contact
 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
 * keyboard-operable Contact disclosure instead.
 */
.app-main {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  flex: 1;
  min-height: 0;
}

@media (min-width: 1000px) {
  .app-main {
    grid-template-columns: auto minmax(0, 1fr) minmax(230px, 280px);
  }
}

.rail {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.5rem 0.4rem;
  border-right: 1px solid var(--divider);
  min-width: 5rem;
}

.rail-item {
  text-align: left;
  background: transparent;
  border-color: transparent;
  color: var(--text-secondary);
  padding: 0.2rem 0.5rem;
}

/* Keep the new local destination from widening the compact browsing rail. */
.rail-done {
  width: 5rem;
  white-space: normal;
}

.rail-item:hover {
  color: var(--text-primary);
}

.rail-item[aria-current='page'],
.rail-item[aria-expanded='true'] {
  color: var(--text-primary);
  background: var(--surface-raised);
  border-color: var(--divider);
}

