.rail-spacer {
  flex: 1;
}

.central {
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Contact context column. */
.contact-column {
  border-left: 1px solid var(--divider);
  background: var(--surface-contact);
  overflow-y: auto;
  padding: 0.6rem;
  min-height: 0;
}

.contact-title {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-secondary);
  margin: 0 0 0.4rem;
}

.contact-identity {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  margin: 0;
  overflow-wrap: anywhere;
}

.contact-name {
  font-weight: 600;
}

.contact-search {
  background: none;
  border: 0;
  padding: 0;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.contact-search:hover { text-decoration: underline; }
.contact-recent { margin-top: 2rem; }
.contact-recent h3 { font-size: 0.85rem; font-weight: 500; color: var(--text-secondary); }
.contact-recent ul { list-style: none; padding: 0; }
.contact-recent li { margin: 0.65rem 0; }
.contact-recent button { text-align: left; overflow-wrap: anywhere; }
.mail-search { padding: 1rem; border-bottom: 1px solid var(--divider); }
.mail-search-entry { display: flex; gap: 0.5rem; flex-wrap: wrap; margin: 0.5rem 0; }
.mail-search-entry input { flex: 1 1 16rem; min-width: 0; }
.mail-search p { max-width: 75ch; font-size: 0.85rem; color: var(--text-secondary); }
.search-cache-toggle { font-size: 0.85rem; }
.contact-mailbox {
  color: var(--text-secondary);
  font-size: 0.8rem;
}

.contact-unknown {
  color: var(--text-secondary);
  font-size: 0.8rem;
  margin: 0;
}

/* Utility disclosures overlay the central surface; they are never columns. */
.utility-drawer {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(460px, 92vw);
  background: var(--surface-contact);
  border-left: 1px solid var(--divider);
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.35);
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
  z-index: 30;
}

.utility-drawer:focus {
  outline: none;
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.drawer-header h2 {
  font-size: 0.95rem;
  margin: 0;
}

/*
 * Compact conversation list (DESIGN.md "Conversation Row"): 36px rows on 12px
 * type in two weights, separated by rhythm alone (no per-row dividers). The
 * row highlight is inset 6px from both pane edges; the 44px left gutter holds
 * the selection checkbox and the read marker, so sender names, date captions
 * and the split tabs share the 50px content inset.
 */
.inbox-scroll {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  height: 100%;
  min-height: 0;
  /* Row columns size from the list width (cqi), never from one row's content. */
  container-type: inline-size;
}

/*
 * Flex (not grid) so the bounded trailing region cannot starve the subject.
 * The sender column is sized from the list width, so it stays aligned on
 * every row and gives up width first as the pane narrows: 132px from a
 * ~700px list, ~115px at the 1030px window, 96px at its floor. Only if a row
 * still cannot fit its subject/snippet floor does that row's sender shrink
 * further (to 72px); the metadata keeps its full content.
 */
.inbox-row {
  display: flex;
  color: var(--warning);
  font-size: 0.85rem;
}

/* UX-03 discovery overlays: input owns keyboard focus; covered shell is inert. */
.cached-coverage { margin: 0; padding: .4rem 1rem; color: var(--text-muted, #bbb); font-size: .85rem; }

/* UX-04 single-slot action notice: in-flow, never covers rows or reader controls. */
.action-notice {
  display: flex;
  gap: .75rem;
  align-items: center;
  flex-wrap: wrap;
  min-height: 1rem;
  padding: .4rem 1rem;
  border-bottom: 1px solid var(--divider);
}
/* The empty region stays rendered at zero height/padding (never display:none):
   a hidden live region is removed from the accessibility tree and inserted
   content at the moment it becomes rendered may not be announced. */
.action-notice-empty { min-height: 0; padding: 0; border-bottom: none; }
.action-notice-text { margin: 0; font-size: .85rem; display: flex; gap: .5rem; flex-wrap: wrap; align-items: baseline; }
.action-notice-label { color: var(--text-primary); font-weight: 600; }
.action-notice-status { color: var(--text-secondary); }
.action-notice-expired { color: var(--warning); }
.action-notice-undo { display: flex; gap: .4rem; align-items: center; }
.action-notice-undo kbd { font-size: .75rem; color: var(--text-secondary); }
.action-backdrop { position: fixed; inset: 0; z-index: 100; background: #0008; display: flex; align-items: flex-start; justify-content: center; padding: min(15vh, 6rem) 1rem 1rem; }
.action-overlay { width: min(46rem, 100%); max-height: 75vh; overflow: auto; background: var(--surface-raised); color: var(--text-primary); border: 1px solid #56534e; border-radius: .85rem; padding: 0; box-shadow: 0 1rem 4rem #0008; }
.action-overlay .action-heading { display: flex; align-items: center; gap: .8rem; margin: 0 1.5rem; padding: 1.2rem 0; border-bottom: 1px solid #56534e; color: #c9c4bc; font-size: .9rem; }
.action-heading > span { font-size: 1.5rem; line-height: 1; }
.action-overlay input { box-sizing: border-box; width: 100%; padding: 1.5rem; color: var(--text-primary); background: transparent; border: 0; border-radius: 0; font: inherit; font-size: 1.5rem; }
.action-overlay input::placeholder { color: #c9c4bc; }
.action-overlay input:focus-visible { outline: 2px solid var(--focus-accent); outline-offset: -4px; }
.action-overlay ul { list-style: none; padding: 0; margin: 0; }
.action-overlay li { display: flex; align-items: center; gap: 1rem; padding: 1rem 1.5rem; cursor: pointer; min-width: 0; }
.action-overlay li.highlighted { background: var(--focus-fill); }
.action-overlay li[aria-disabled='true'] { cursor: default; }
.action-icon { width: 1.4rem; height: 1.4rem; flex-shrink: 0; color: #c9c4bc; }
.action-copy { display: flex; flex: 1; flex-direction: column; gap: .3rem; min-width: 0; overflow-wrap: anywhere; }
.action-disabled-reason { color: #d4cfc7; font-size: .8rem; }
.action-overlay kbd { flex-shrink: 0; padding: .15rem .4rem; border-radius: .25rem; background: #66615b; color: #fff; font: inherit; font-size: .8rem; }
.action-hint, .action-overlay > [role='status'] { margin: 0; padding: .8rem 1.5rem; color: #c9c4bc; font-size: .8rem; }
.action-hint { border-top: 1px solid var(--divider); }

/* UX-06: compact overlapping Inbox views, no folder or classifier metaphor. */
.split-nav { display: flex; align-items: center; flex-wrap: wrap; gap: .4rem; padding-top: .4rem; font-size: .85rem; }
.split-nav button { max-width: 100%; overflow-wrap: anywhere; cursor: pointer; }
.split-nav [aria-current="page"], .split-nav [aria-pressed="true"] { color: var(--focus-accent); background: var(--focus-fill); border-color: var(--focus-accent); }
.split-count { margin-inline-start: .3rem; font-variant-numeric: tabular-nums; }
.split-editor { max-height: 38vh; overflow: auto; padding: .5rem 0; font-size: .85rem; }
.split-editor p { max-width: 75ch; margin: .35rem 0 .6rem; }
.split-editor fieldset { border: 0; padding: 0; margin: 0 0 .6rem; display: flex; flex-wrap: wrap; gap: .6rem 1rem; align-items: center; }
.split-editor label { display: flex; align-items: center; gap: .4rem; max-width: 100%; }
.split-editor input:not([type="checkbox"]) { min-width: 0; width: 15rem; max-width: 100%; padding: .3rem; font: inherit; }
.split-editor select { background: var(--surface-raised); color: var(--text-primary); border: 1px solid var(--divider); padding: .3rem; font: inherit; }
.split-editor :is(input, select):focus-visible { outline: 2px solid var(--focus-accent); outline-offset: 1px; }
.split-editor input::placeholder { color: var(--text-secondary); opacity: 1; }

/* UX-05 selection action bar: compact, in normal flow above the list. */
.selection-bar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .5rem 1rem;
  padding: .4rem .6rem;
  border-bottom: 1px solid var(--divider);
  font-size: .85rem;
}
.selection-scope { margin: 0; }
.selection-loaded-scope { color: var(--text-secondary); }
.selection-actions { display: flex; flex-wrap: wrap; gap: .4rem; }
.selection-limit { margin: 0; flex-basis: 100%; color: var(--warning); }
.reader-selection-scope {
  margin: 0;
  padding: .4rem .6rem;
  border-bottom: 1px solid var(--divider);
  color: var(--text-secondary);
  font-size: .85rem;
}

/* UX-05 Activity group sections. */
.activity-groups { margin-bottom: 1rem; }
.activity-groups-title { margin: .2rem 0 .4rem; font-size: .9rem; }
.activity-group-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: .35rem; }
.activity-group-toggle { width: 100%; text-align: left; cursor: pointer; }
.activity-group-detail { margin-top: .4rem; padding: .5rem; border: 1px solid var(--divider); border-radius: .3rem; }
.activity-group-request { margin: 0 0 .4rem; color: var(--text-secondary); font-size: .8rem; overflow-wrap: anywhere; }
.activity-group-members { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: .35rem; }
.activity-group-member { display: flex; flex-wrap: wrap; align-items: baseline; gap: .4rem; }
